insert into chunks (document_id, chunk_index, heading, content) values
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 200, 'B6.5.25', 'a) zajišťovací vztah v celém rozsahu, nebo b) část zajišťovacího vztahu (což znamená, že zajišťovací účetnictví pro zbytek zajišťovacího vztahu pokračuje).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 201, 'B6.5.26', 'a) zajišťovací vztah již nesplňuje cíl řízení rizik, na jehož základě naplňoval podmínky zajišťovacího účetnictví, tj. účetní jednotka již nesleduje daný cíl řízení rizik); b) zajišťovací nástroj nebo nástroje byly prodány nebo ukončeny ve vztahu k celému objemu, který byl součástí zajišťovacího vztahu); c) již neexistuje ekonomický vztah mezi zajištěnou položkou a zajišťovacím nástrojem, případně dopad úvěrového rizika začíná být určující pro změny hodnoty, které vyplývají z daného ekonomického vztahu.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 202, 'B6.5.27', 'a) při rebalancování zajišťovacího vztahu by mohl být zajišťovací poměr upraven tak, že část objemu zajištěné položky již není součástí zajišťovacího vztahu (viz odstavec B6.5.20); proto je zajišťovací účetnictví ukončeno pouze pro objem zajištěné položky, který již není součástí zajišťovacího vztahu, nebo b) pokud výskyt části objemu zajištěné položky, která představuje očekávanou transakci (nebo její složku) již není vysoce pravděpodobný, je zajišťovací účetnictví ukončeno pouze pro objem této zajištěné položky, jejíž výskyt již není vysoce pravděpodobný. Pokud však účetní jednotka v minulosti označovala zajištění očekávaných transakcí a následně stanovila, že výskyt těchto očekávaných transakcí se již nepředpokládá, zpochybňuje to schopnost účetní jednotky přesně předvídat očekávané transakce z hlediska předvídání obdobných očekávaných transakcí. To ovlivňuje posouzení, zda jsou podobné očekávané transakce vysoce pravděpodobné (viz odstavec 6.3.3), a zda jsou tudíž způsobilé jako zajištěné položky.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 203, 'B6.5.28', 'a) u zajišťovacího nástroje dojde k tak závažnému zhoršení kreditního rizika, že jej účetní jednotka nahradí ji novým zajišťovacím nástrojem. To znamená, že u původního zajišťovacího vztahu se nepodařilo dosáhnout cíle v oblasti řízení rizik, a proto je přerušen v celém rozsahu. Nový zajišťovací nástroj je určen jako zajištění stejného rizika, které bylo zajištěno již dříve, a tvoří nový zajišťovací vztah. Proto se změny v reálné hodnotě nebo změny peněžních toků zajištěné položky oceňují od data určení tohoto nového zajišťovacího vztahu a s odkazem na něj, a nikoli od data, kdy byl určen původní zajišťovací vztah; b) zajišťovací vztah je ukončen před koncem své splatnosti. Zajišťovací nástroj v tomto zajišťovacím vztahu lze označit jako zajišťovací nástroj v jiném zajišťovacím vztahu (například při úpravě zajišťovacího poměru při rebalancování zvýšením objemu zajišťovacího nástroje nebo při označení zcela nového zajišťovacího vztahu). Účtování o časové hodnotě opcí'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 204, 'B6.5.29', 'a) časová hodnota opce se vztahuje k zajištěné položce spojené s transakcí, pokud je podstatou zajištěné položky transakce, u níž má časová hodnota povahu nákladů na tuto transakci. Příkladem je situace, kdy se časová hodnota opce vztahuje k zajištěné položce, v důsledku čehož je uznána položka, jejíž prvotní ocenění zahrnuje transakční náklady (účetní jednotka například zajistí koupi komodity bez ohledu na to, zda se jedná o očekávanou transakci nebo o závazný příslib, proti komoditnímu riziku, a transakční náklady zahrne do prvotního ocenění těchto zásob). V důsledku zahrnutí časové hodnoty opce do prvotního ocenění určité zajištěné položky ovlivní tato časová hodnota hospodářský výsledek zároveň s danou zajištěnou položkou. Obdobně by účetní jednotka, která zajišťuje prodej určité komodity bez ohledu na to, zda se jedná o očekávanou transakci nebo o závazný příslib, zahrnula časovou hodnotu opce do nákladů souvisejících s tímto prodejem (časová hodnota by tudíž byla uznána do hospodářského výsledku ve stejném období jako výnosy ze zajištěného prodeje);'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 205, 'B6.5.29', 'b) časová hodnota opce se vztahuje k zajištěné položce spojené s časovým obdobím, pokud je povaha zajištěné položky taková, že časová hodnota má charakter nákladů na získání ochrany proti riziku v určitém časovém období (ale zajištěná položka nevyústí v transakci, která zahrnuje pojem transakčních nákladů v souladu s písmenem a)). Jestliže jsou například zásoby komodity zajištěny proti snížení reálné hodnoty po dobu šesti měsíců s využitím komoditní opce s odpovídající dobou trvání, časová hodnota této opce by byla přiřazena hospodářskému výsledku (tj. odepisována na systematické a racionální bázi) v průběhu tohoto šestiměsíčního období. Jiným příkladem je zajištění čisté investice do zahraniční jednotky, která je zajišťována po dobu 18 měsíců s využitím měnové opce, v jejímž důsledku dojde k přiřazení časové hodnoty této opce v průběhu tohoto osmnáctiměsíčního období.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 206, 'B6.5.30', 'a) jestliže horní limit zajišťuje zvýšení úrokových měr v prvních třech letech z celkové doby trvání pětiletého dluhopisu s proměnlivou úrokovou mírou, časová hodnota tohoto horního limitu se odepisuje po dobu prvních tří let, nebo b) jestliže horní limit představuje forward start opci, která zajišťuje zvýšení úrokové míry pro druhý a třetí rok z celkové doby trvání pětiletého dluhopisu s proměnlivou úrokovou mírou, časová hodnota tohoto horního limitu se odepisuje v průběhu druhého a třetího roku.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 207, 'B6.5.31', 'a) zajištěné položce spojené s transakcí, rovná se částka časové hodnoty na konci zajišťovacího vztahu, která upravuje zajištěnou položku nebo která je reklasifikována do hospodářského výsledku (viz odst. 6.5.15 písm. b)), nule; b) zajištěné položce spojené s časovým obdobím, rovnají se náklady na amortizaci ve vztahu k časové hodnotě nule.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 208, 'B6.5.33', 'a) jestliže je při zahájení zajišťovacího vztahu skutečná časová hodnota vyšší než přiřaditelná časová hodnota, účetní jednotka: i) stanoví částku kumulovanou v samostatné složce vlastního kapitálu na základě přiřaditelné časové hodnoty a ii) zaúčtuje rozdíly změn reálné hodnoty mezi oběma těmito časovými hodnotami do hospodářského výsledku; b) jestliže je při zahájení zajišťovacího vztahu skutečná časová hodnota nižší než přiřaditelná časová hodnota, stanoví účetní jednotka částku kumulovanou v samostatné složce vlastního kapitálu odkazem na nižší z následujících kumulativních změn reálné hodnoty: i) skutečné časové hodnoty a ii) přiřaditelné časové hodnoty. Všechny zbývající změny v reálné hodnotě skutečné časové hodnoty se uznávají do hospodářského výsledku. Účtování o forwardové části forwardových smluv a o měnovém bazickém rozpětí (basis spread) finančních nástrojů'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 209, 'B6.5.34', 'a) forwardový prvek forwardové smlouvy se vztahuje k zajištěné položce spojené s transakcí, pokud je podstatou zajištěné položky transakce, u níž má forwardový prvek povahu nákladů na tuto transakci. Příkladem je situace, kdy se forwardový prvek vztahuje k zajištěné položce, v důsledku čehož je uznána položka, jejíž prvotní ocenění zahrnuje transakční náklady (účetní jednotka například zajistí koupi zásob vyjádřenou v cizí měně bez ohledu na to, zda se jedná o očekávanou transakci nebo o závazný příslib, proti měnovému riziku a transakční náklady zahrne do prvotního ocenění těchto zásob). V důsledku zahrnutí forwardového prvku do prvotního ocenění určité zajištěné položky ovlivní tento forwardový prvek hospodářský výsledek zároveň s danou zajištěnou položkou. Obdobně by účetní jednotka, která zajišťuje prodej určité komodity vyjádřené v cizí měně proti měnovému riziku bez ohledu na to, zda se jedná o očekávanou transakci nebo o závazný příslib, zahrnula forwardový prvek do nákladů souvisejících s tímto prodejem (forwardový prvek by tudíž byl uznán do hospodářského výsledku ve stejném období jako výnosy ze zajištěného prodeje);'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 210, 'B6.5.34', 'b) forwardový prvek forwardové smlouvy se vztahuje k zajištěné položce spojené s časovým obdobím, pokud je povaha zajištěné položky taková, že forwardový prvek má povahu nákladů na získání ochrany proti riziku v určitém časovém období (ale zajištěná položka nevyústí v transakci, která zahrnuje pojem transakčních nákladů v souladu s písmenem a)). Jestliže jsou například zásoby komodity zajištěny proti změnám reálné hodnoty po dobu šesti měsíců s využitím komoditní forwardové smlouvy s odpovídající dobou trvání, forwardový prvek této forwardové smlouvy by byl přiřazen hospodářskému výsledku (tj. odepisován na systematické a racionální bázi) v průběhu tohoto šestiměsíčního období. Jiným příkladem je zajištění čisté investice do zahraniční jednotky, která je zajišťována po dobu 18 měsíců s využitím forwardové měnové smlouvy, v jejímž důsledku dojde k přiřazení forwardového prvku forwardové smlouvy v průběhu tohoto osmnáctiměsíčního období.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 211, 'B6.5.36', 'a) zajištěné položce spojené s transakcí, rovná se částka týkající se forwardového prvku na konci zajišťovacího vztahu, která upravuje zajištěnou položku nebo která je reklasifikována do hospodářského výsledku (viz odst. 6.5.15 písm. b) a odstavec 6.5.16)), nule; b) zajištěné položce spojené s časovým obdobím, rovnají se náklady na amortizaci ve vztahu k forwardovému prvku nule.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 212, 'B6.5.38', 'a) jestliže je při zahájení zajišťovacího vztahu absolutní částka skutečného forwardového prvku vyšší než přiřaditelný forwardový prvek, účetní jednotka: i) stanoví částku kumulovanou v samostatné složce vlastního kapitálu na základě přiřaditelného forwardového prvku a ii) zaúčtuje rozdíly změn reálné hodnoty mezi oběma těmito forwardovými prvky do hospodářského výsledku; b) jestliže je při zahájení zajišťovacího vztahu absolutní částka skutečného forwardového prvku nižší než přiřaditelný forwardový prvek, účetní jednotka stanoví částku kumulovanou v samostatné složce vlastního kapitálu odkazem na nižší z následujících kumulativních změn v reálné hodnotě: i) absolutní částky skutečného forwardového prvku a ii) absolutní částky přiřaditelného forwardového prvku. Všechny zbývající změny v reálné hodnotě skutečného forwardového prvku se uznávají do hospodářského výsledku.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 213, 'B6.5.39', 'Zajištění skupiny položek (oddíl 6.6) Zajištění čisté pozice Způsobilost pro zajišťovací účetnictví a použití čisté pozice'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 214, 'B6.6.4', 'Aplikace požadavků na efektivnost zajištění na za jištění čisté pozice'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 215, 'B6.6.5', 'a) změnou reálné hodnoty forwardové měnové smlouvy společně se změnami hodnoty závazných příslibů prodeje souvisejícími s měnovým rizikem a b) změnami hodnoty závazných příslibů koupě souvisejícími s měnovým rizikem.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 216, 'B6.6.6', 'Zajištění peněžních toků,které představuje čistou pozici'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 217, 'B6.6.8', 'a) prvních 60 CM koupí strojů typu A, které budou dle očekávání ovlivňovat hospodářský výsledek ze třetího účetního období po následujících deset účetních období; b) prvních 40 CM koupí strojů typu B, které budou dle očekávání ovlivňovat hospodářský výsledek ze čtvrtého účetního období po následujících 20 účetních období; c) prvních 50 CM koupí suroviny A, které budou dle očekávání obdrženy ve třetím účetním období a poté prodány, tj. ovlivní hospodářský výsledek v tomto a v následujícím účetním období. Specifikace povahy objemů očekávaných transakcí by zahrnovala takové aspekty, jako je například model odpisů hmotných aktiv pro položky pozemků, budov a zařízení téhož druhu, jestliže je povaha těchto položek taková, že by se model odpisů hmotných aktiv mohl lišit v závislosti na tom, jak účetní jednotka tyto položky využívá. Jestliže například účetní jednotka využívá položky strojů typu A ve dvou různých výrobních procesech, u nichž se užívá v jednom případě metoda lineárních odpisů hmotných aktiv v průběhu deseti účetních období a ve druhém případě metoda výkonových odpisů, rozčlenila by ve své dokumentaci očekávaného objemu koupí strojů typu A tento objem podle toho, který model odpisů hmotných aktiv by pro něj byl použit.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 218, 'B6.6.9', 'a) změnu reálné hodnoty měnové smlouvy společně se změnami hodnoty vysoce pravděpodobných očekávaných prodejů souvisejícími s měnovým rizikem se b) změnami hodnoty vysoce pravděpodobných očekávaných koupí souvisejícími s měnovým rizikem. Účetní jednotka však uzná částky týkající se forwardových měnových smluv pouze do doby, dokud nejsou vysoce pravděpodobné očekávané prodejní transakce uznány v účetní závěrce; ve stejné době jsou uznány i zisky nebo ztráty z těchto očekávaných transakcí (tj. změna hodnoty připadající na změnu měnového kurzu mezi označením zajišťovacího vztahu a uznáním výnosu).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 219, 'B6.6.10', 'Určení vrstev skupin položek jako zajištěných položek'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 220, 'B6.6.12', 'Vykazování zisků nebo ztrát ze zajišťovacího nástroje'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 221, 'DATUM ÚČINNOSTI A PŘECHODNÁ USTANOVENÍ (KAPITOLA 7)', 'Přechodná ustanovení (oddíl 7.2) Finanční aktiva určená k obchodování'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 222, 'B7.2.1', 'Znehodnocení'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 223, 'DEFINICE (DODATEK A)', 'Deriváty'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 224, 'BA.5', 'Finanční aktiva a závazky určené k obchodování'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 225, 'BA.7', 'a) derivátové závazky, které nejsou vykázány jako zajišťovací nástroje; b) závazky dodat finanční aktiva vypůjčená prodejci „na krátko“ (tzn. účetní jednotkou, která prodá půjčená finanční aktiva, jež dosud nevlastní); c) finanční závazky, které vznikly se záměrem jejich zpětné koupě v brzké době (např. kotované dluhové nástroje, které jejich emitent může koupit zpět v brzké době v závislosti na změnách jejich reálné hodnoty), a d) finanční závazky, které jsou součástí portfolia společně spravovaných identifikovaných finančních nástrojů, jež v poslední době vykázalo známky obchodování.')
